"""Read-only reports over orders, the catalog and the inventory."""
from __future__ import annotations

from decimal import Decimal

from .money import ZERO, round_money

COUNTED_STATUSES = ("shipped", "partially_refunded", "refunded")


def units_sold(order, sku: str) -> int:
    """Units of `sku` the customer kept: bought minus refunded."""
    return order.quantity_of(sku) - order.refunded_quantity(sku)


def sales_by_category(orders, catalog) -> dict[str, Decimal]:
    """Gross sales (unit price x units kept) per category, over shipped and refunded orders.

    Cancelled and still-reserved orders do not count. Categories with no sales are left out. Amounts are rounded
    to the cent.
    """
    out: dict[str, Decimal] = {}
    for order in orders:
        if order.status not in COUNTED_STATUSES:
            continue
        for line in order.lines:
            kept = units_sold(order, line.sku)
            if kept <= 0:
                continue
            cat = catalog.get(line.sku).category
            out[cat] = out.get(cat, ZERO) + line.unit_price * kept
    return {k: round_money(v) for k, v in sorted(out.items())}


def top_products(orders, n: int = 3) -> list[tuple[str, int]]:
    """The n SKUs with the most units kept over counted orders, as (sku, units), most first; ties by SKU A-Z.

    SKUs whose units were all refunded are left out. n larger than the number of SKUs returns them all.
    """
    if n < 0:
        raise ValueError("n cannot be negative")
    totals: dict[str, int] = {}
    for order in orders:
        if order.status not in COUNTED_STATUSES:
            continue
        for line in order.lines:
            totals[line.sku] = totals.get(line.sku, 0) + units_sold(order, line.sku)
    ranked = sorted(((s, u) for s, u in totals.items() if u > 0), key=lambda x: (-x[1], x[0]))
    return ranked[:n]


def inventory_valuation(inventory, catalog, include_inactive: bool = False) -> Decimal:
    """On-hand units x price for catalog SKUs (inactive products only when asked), rounded to the cent."""
    total = ZERO
    for p in catalog.products(include_inactive=include_inactive):
        total += p.price * inventory.on_hand(p.sku)
    return round_money(total)


def low_stock_report(inventory, catalog, threshold: int = 5) -> list[str]:
    """'SKU name: N left' lines for active products whose available units are at or below threshold, by SKU."""
    lines = []
    for p in catalog.products():
        avail = inventory.available(p.sku)
        if avail <= threshold:
            lines.append(f"{p.sku} {p.name}: {avail} left")
    return lines


def average_order_value(orders) -> Decimal:
    """Mean of (total - refunded) over counted orders, rounded to the cent; 0.00 when there are none."""
    values = [o.totals["total"] - o.refunded_amount() for o in orders if o.status in COUNTED_STATUSES]
    if not values:
        return round_money(ZERO)
    return round_money(sum(values, ZERO) / len(values))
=== storage.py ===
"""JSON persistence of the whole service state, with atomic writes and a migration from schema version 1.

Version 2 (current): prices and amounts are decimal strings ("12.30").
Version 1: product prices were integer cents under "price_cents"; there were no customer regions (all "US-CA").
"""
from __future__ import annotations

import json
import os
import tempfile
from dataclasses import dataclass
from decimal import Decimal

from .catalog import Catalog
from .inventory import Inventory
from .models import Customer, ValidationError
from .orders import OrderService

SCHEMA_VERSION = 2


@dataclass
class State:
    catalog: Catalog
    inventory: Inventory
    orders: OrderService


def new_state(clock=None) -> State:
    catalog, inventory = Catalog(), Inventory(clock)
    return State(catalog, inventory, OrderService(catalog, inventory))


def to_dict(state: State) -> dict:
    return {"version": SCHEMA_VERSION, "catalog": state.catalog.to_list(), "inventory": state.inventory.to_dict(),
            "customers": [c.to_dict() for c in state.orders.customers.values()], **state.orders.to_dict()}


def migrate(data: dict) -> dict:
    """Bring older files up to SCHEMA_VERSION. Returns a new dict; the input is not changed."""
    data = json.loads(json.dumps(data))
    version = data.get("version", 1)
    if version > SCHEMA_VERSION:
        raise ValidationError(f"state file version {version} is newer than this program ({SCHEMA_VERSION})")
    if version == 1:
        for p in data.get("catalog", []):
            if "price_cents" in p:
                p["price"] = str(Decimal(int(p.pop("price_cents"))) / 100)
        for c in data.get("customers", []):
            c.setdefault("region", "US-CA")
        data["version"] = 2
    return data


def from_dict(data: dict, clock=None) -> State:
    data = migrate(data)
    catalog = Catalog.from_list(data.get("catalog", []))
    inventory = Inventory.from_dict(data.get("inventory", {}), clock)
    orders = OrderService(catalog, inventory, {c["id"]: Customer.from_dict(c) for c in data.get("customers", [])})
    orders.load_orders(data)
    return State(catalog, inventory, orders)


def save(state: State, path: str) -> None:
    """Write the state as JSON. The file is replaced atomically, so a crash never leaves half a file."""
    text = json.dumps(to_dict(state), indent=1, sort_keys=True)
    folder = os.path.dirname(os.path.abspath(path))
    fd, tmp = tempfile.mkstemp(prefix=".state-", suffix=".tmp", dir=folder)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(text)
        os.replace(tmp, path)
    except BaseException:
        if os.path.exists(tmp):
            os.remove(tmp)
        raise


def load(path: str, clock=None) -> State:
    """Read a state file; a missing file gives an empty state."""
    if not os.path.exists(path):
        return new_state(clock)
    with open(path, encoding="utf-8") as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError as e:
            raise ValidationError(f"{path} is not valid JSON: {e}") from None
    return from_dict(data, clock)
